        assert_eq!(code(line), ErrorCode::InvalidParameterValue);
        let line = r#"{"Command": "CreateQueue", "QueueName": "q", "Attributes": 5}"#;
        assert_eq!(code(line), ErrorCode::InvalidParameterValue);
    }

