        } else {
            Err(Error::new(
                ErrorCode::ReceiptHandleExpired,
                format!("receipt handle {handle:?} is no longer usable"),
            ))
        }
    }
}

fn sent(id: MessageId, sequence_number: Option<u64>) -> Reply {
    Reply::Sent { message_id: id, sequence_number }
}

fn unsupported(what: &str) -> Error {
    Error::new(ErrorCode::UnsupportedOperation, format!("{what} is not supported"))
}

