#[test]
fn create_queue_applies_its_rules_in_order() {
    let mut s = Session::new();
    s.create("standard");
    let create = |name: &str, attributes| json!({"Command": "CreateQueue", "QueueName": name, "Attributes": attributes});
    assert_eq!(s.err(create("a.fifo", json!({}))), "QueueNameInvalid");
    assert_eq!(s.err(create("a", json!({"Fifo": true}))), "QueueNameInvalid");
    assert_eq!(s.err(create("a", json!({"ContentBasedDeduplication": true}))), "InvalidParameterValue");
    assert_eq!(s.err(create("a", json!({"MaxReceiveCount": 1}))), "InvalidParameterValue");
    assert_eq!(s.err(create("a", json!({"DeadLetterQueue": "standard"}))), "InvalidParameterValue");
    assert_eq!(
        s.err(create("a", json!({"DeadLetterQueue": "ghost", "MaxReceiveCount": 1}))),
        "QueueDoesNotExist"
    );
    assert_eq!(
        s.err(create("a.fifo", json!({"Fifo": true, "DeadLetterQueue": "standard", "MaxReceiveCount": 1}))),
        "InvalidParameterValue"
    );
